        return line, None
    name = m.group(1).lower().replace("_", "-")
    spec = m.group(2).strip() if m.group(2) else None
    return name, spec


def _extract_package_json(
    repo_path: Path, file_entries: list[FileEntry]
) -> list[Dependency]:
    pkg_path = repo_path / "package.json"
    if not pkg_path.exists():
