1 | import { useState, useEffect, useRef } from 'react';
2 | import { useParams, Link } from 'react-router-dom';
3 | import { api } from '../api/client';
4 | import type {
5 |   ProjectSummary,
6 |   TechnologyDetection,
7 |   Dependency,
8 |   FileEntry,
9 |   Component,
10 |   Relationship,
11 | } from '../types/knowledge';
12 | import OverviewPanel from '../components/OverviewPanel';
13 | import TechnologiesPanel from '../components/TechnologiesPanel';
14 | import DependenciesPanel from '../components/DependenciesPanel';
15 | import RepositoryPanel from '../components/RepositoryPanel';
16 | import ArchitectureGraph from '../components/ArchitectureGraph';
17 | 
18 | type Tab = 'overview' | 'technologies' | 'dependencies' | 'architecture' | 'repository';
19 | 
20 | const TABS: { id: Tab; label: string }[] = [
21 |   { id: 'overview', label: 'Overview' },
22 |   { id: 'technologies', label: 'Technologies' },
23 |   { id: 'dependencies', label: 'Dependencies' },
24 |   { id: 'architecture', label: 'Architecture' },
25 |   { id: 'repository', label: 'Repository' },
26 | ];
27 | 
28 | export default function DashboardPage() {
29 |   const { projectId } = useParams<{ projectId: string }>();
30 |   const [summary, setSummary] = useState<ProjectSummary | null>(null);
31 |   const [activeTab, setActiveTab] = useState<Tab>('overview');
32 |   const [error, setError] = useState<string | null>(null);
33 | 
34 |   // Lazy per-tab data
35 |   const [technologies, setTechnologies] = useState<TechnologyDetection[] | null>(null);
36 |   const [dependencies, setDependencies] = useState<Dependency[] | null>(null);
37 |   const [files, setFiles] = useState<FileEntry[] | null>(null);
38 |   const [components, setComponents] = useState<Component[] | null>(null);
39 |   const [relationships, setRelationships] = useState<Relationship[] | null>(null);
40 | 
41 |   // Track which tabs have been fetched
42 |   const fetched = useRef<Set<Tab>>(new Set());
43 |   const pollTimer = useRef<ReturnType<typeof setInterval> | null>(null);
44 | 
45 |   // Polling until ready/error
46 |   useEffect(() => {
47 |     if (!projectId) return;
48 | 
49 |     async function poll() {
50 |       try {
51 |         const data: ProjectSummary = await api.getProject(projectId!);
52 |         setSummary(data);
53 |         if (data.status === 'ready' || data.status === 'error') {
54 |           if (pollTimer.current) clearInterval(pollTimer.current);
55 |           if (data.status === 'error') {
56 |             setError(data.error_message ?? 'Analysis failed.');
57 |           }
58 |         }
59 |       } catch {
60 |         setError('Failed to fetch project status.');
61 |         if (pollTimer.current) clearInterval(pollTimer.current);
62 |       }
63 |     }
64 | 
65 |     poll();
66 |     pollTimer.current = setInterval(poll, 2000);
67 |     return () => {
68 |       if (pollTimer.current) clearInterval(pollTimer.current);
69 |     };
70 |   }, [projectId]);
71 | 
72 |   // Lazy-fetch tab data when a tab is first activated (only when ready)
73 |   useEffect(() => {
74 |     if (!projectId || !summary || summary.status !== 'ready') return;
75 |     if (fetched.current.has(activeTab)) return;
76 |     fetched.current.add(activeTab);
77 | 
78 |     switch (activeTab) {
79 |       case 'technologies':
80 |         api.getTechnologies(projectId).then((d: TechnologyDetection[]) => setTechnologies(d)).catch(() => setTechnologies([]));
81 |         break;
82 |       case 'dependencies':
83 |         api.getDependencies(projectId).then((d: Dependency[]) => setDependencies(d)).catch(() => setDependencies([]));
84 |         break;
85 |       case 'repository':
86 |         api.getTree(projectId).then((d: FileEntry[]) => setFiles(d)).catch(() => setFiles([]));
87 |         break;
88 |       case 'architecture':
89 |         api.getArchitecture(projectId).then((d: { components: Component[]; relationships: Relationship[] }) => {
90 |           setComponents(d.components ?? []);
91 |           setRelationships(d.relationships ?? []);
92 |         }).catch(() => { setComponents([]); setRelationships([]); });
93 |         break;
94 |       case 'overview':
95 |         // Also pre-fetch technologies for the overview chips
96 |         if (!fetched.current.has('technologies')) {
97 |           fetched.current.add('technologies');
98 |           api.getTechnologies(projectId).then((d: TechnologyDetection[]) => setTechnologies(d)).catch(() => setTechnologies([]));
99 |         }
100 |         break;
101 |     }
102 |   }, [activeTab, summary, projectId]);
103 | 
104 |   const isLoading = !summary || summary.status === 'pending' || summary.status === 'analyzing';
105 | 
106 |   return (
107 |     <div className="dashboard">
108 |       {/* Header */}
109 |       <header className="dash-header">
110 |         <Link to="/" className="dash-back">← CodeAtlas</Link>
111 |         <div className="dash-title">
112 |           <span className="dash-name">{summary?.name ?? projectId}</span>
113 |           {summary && <StatusBadge status={summary.status} />}
114 |         </div>
115 |         {summary && (
116 |           <a className="dash-repo-link" href={summary.repository_url} target="_blank" rel="noreferrer">
117 |             {summary.repository_url}
118 |           </a>
119 |         )}
120 |       </header>
121 | 
122 |       {/* Error banner */}
123 |       {error && <div className="dash-error-banner">{error}</div>}
124 | 
125 |       {/* Loading state */}
126 |       {isLoading && !error && (
127 |         <div className="dash-loading">
128 |           <span className="spinner spinner--lg" />
129 |           <p>Analyzing repository…</p>
130 |         </div>
131 |       )}
132 | 
133 |       {/* Dashboard content */}
134 |       {!isLoading && summary && (
135 |         <>
136 |           <nav className="dash-tabs">
137 |             {TABS.map(tab => (
138 |               <button
139 |                 key={tab.id}
140 |                 className={`dash-tab${activeTab === tab.id ? ' dash-tab--active' : ''}`}
141 |                 onClick={() => setActiveTab(tab.id)}
142 |                 type="button"
143 |               >
144 |                 {tab.label}
145 |               </button>
146 |             ))}
147 |           </nav>
148 | 
149 |           <main className="dash-content">
150 |             {activeTab === 'overview' && (
151 |               <OverviewPanel summary={summary} technologies={technologies ?? []} />
152 |             )}
153 |             {activeTab === 'technologies' && (
154 |               technologies === null
155 |                 ? <div className="panel-loading"><span className="spinner" /> Loading…</div>
156 |                 : <TechnologiesPanel technologies={technologies} />
157 |             )}
158 |             {activeTab === 'dependencies' && (
159 |               dependencies === null
160 |                 ? <div className="panel-loading"><span className="spinner" /> Loading…</div>
161 |                 : <DependenciesPanel dependencies={dependencies} />
162 |             )}
163 |             {activeTab === 'architecture' && (
164 |               components === null || relationships === null
165 |                 ? <div className="panel-loading"><span className="spinner" /> Loading…</div>
166 |                 : <ArchitectureGraph components={components} relationships={relationships} />
167 |             )}
168 |             {activeTab === 'repository' && (
169 |               files === null
170 |                 ? <div className="panel-loading"><span className="spinner" /> Loading…</div>
171 |                 : <RepositoryPanel files={files} />
172 |             )}
173 |           </main>
174 |         </>
175 |       )}
176 |     </div>
177 |   );
178 | }
179 | 
