181 |   const colorMap: Record<ProjectSummary['status'], string> = {
182 |     ready: 'var(--success)',
183 |     analyzing: 'var(--warning)',
184 |     pending: 'var(--warning)',
185 |     error: 'var(--error)',
186 |   };
187 |   return (
188 |     <span className="status-badge" style={{ color: colorMap[status], borderColor: colorMap[status] }}>
189 |       {status}
