1 | import { useState } from 'react';
2 | import type { FileEntry } from '../types/knowledge';
3 | 
4 | interface Props {
5 |   files: FileEntry[];
6 | }
7 | 
8 | interface TreeNode {
9 |   name: string;
10 |   path: string;
11 |   isDir: boolean;
12 |   children: Map<string, TreeNode>;
13 |   file?: FileEntry;
14 | }
15 | 
16 | function buildTree(files: FileEntry[]): TreeNode {
17 |   const root: TreeNode = { name: '', path: '', isDir: true, children: new Map() };
18 |   for (const file of files) {
19 |     const parts = file.path.replace(/^\//, '').split('/');
20 |     let node = root;
21 |     for (let i = 0; i < parts.length; i++) {
22 |       const part = parts[i];
23 |       const currentPath = parts.slice(0, i + 1).join('/');
24 |       if (!node.children.has(part)) {
25 |         node.children.set(part, {
26 |           name: part,
27 |           path: currentPath,
28 |           isDir: i < parts.length - 1,
29 |           children: new Map(),
30 |         });
31 |       }
32 |       node = node.children.get(part)!;
33 |     }
34 |     node.file = file;
35 |     node.isDir = false;
36 |   }
37 |   return root;
38 | }
39 | 
40 | function formatSize(bytes: number): string {
41 |   if (bytes < 1024) return `${bytes} B`;
42 |   if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
43 |   return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
44 | }
45 | 
46 | function TreeNodeView({ node, depth }: { node: TreeNode; depth: number }) {
47 |   const [open, setOpen] = useState(depth < 2);
48 |   const indent = depth * 16;
49 | 
50 |   if (node.isDir) {
51 |     const children = Array.from(node.children.values()).sort((a, b) => {
52 |       // dirs first, then files
53 |       if (a.isDir !== b.isDir) return a.isDir ? -1 : 1;
54 |       return a.name.localeCompare(b.name);
55 |     });
56 |     return (
57 |       <div>
58 |         <button
59 |           className="tree-dir"
60 |           style={{ paddingLeft: indent }}
61 |           onClick={() => setOpen(o => !o)}
62 |           type="button"
63 |         >
64 |           <span className="tree-toggle">{open ? '▾' : '▸'}</span>
65 |           <span className="tree-dir-name">{node.name}</span>
66 |         </button>
67 |         {open && (
68 |           <div>
69 |             {children.map(child => (
70 |               <TreeNodeView key={child.path} node={child} depth={depth + 1} />
71 |             ))}
72 |           </div>
73 |         )}
74 |       </div>
75 |     );
76 |   }
77 | 
78 |   const file = node.file;
79 |   return (
80 |     <div className={`tree-file${file?.is_important ? ' tree-file--important' : ''}`} style={{ paddingLeft: indent }}>
81 |       <span className="tree-file-name">
82 |         {file?.is_important && <span className="tree-important-badge">★</span>}
83 |         {node.name}
84 |       </span>
85 |       {file && (
86 |         <span className="tree-file-size">{formatSize(file.size_bytes)}</span>
87 |       )}
88 |     </div>
89 |   );
90 | }
91 | 
92 | export default function RepositoryPanel({ files }: Props) {
93 |   if (files.length === 0) {
94 |     return <p className="empty-state">No files detected.</p>;
95 |   }
96 | 
97 |   const root = buildTree(files);
98 |   const topLevel = Array.from(root.children.values()).sort((a, b) => {
99 |     if (a.isDir !== b.isDir) return a.isDir ? -1 : 1;
100 |     return a.name.localeCompare(b.name);
101 |   });
102 | 
103 |   return (
104 |     <div className="repo-panel">
105 |       {topLevel.map(node => (
106 |         <TreeNodeView key={node.path} node={node} depth={0} />
107 |       ))}
