/* ── Database Panel ───────────────────────────────── */
.db-panel { display: flex; flex-direction: column; height: 100%; gap: 8px; }
.db-stats { display: flex; gap: 16px; font-size: 12px; color: var(--text-muted); padding: 4px 0; }
.db-stats span::before { content: '• '; color: var(--accent); }
.db-graph-wrap { flex: 1; min-height: 560px; border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; }

.db-placeholder { display: flex; flex-direction: column; align-items: center; justify-content: center; height: 300px; gap: 8px; color: var(--text-muted); }
.db-placeholder-hint { font-size: 12px; }

/* Table node */
.db-table-node {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font-size: 12px;
  min-width: 200px;
  overflow: hidden;
}
.db-table-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 10px;
