.tech-card-header { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.tech-name { font-weight: 600; font-size: 14px; }
.tech-version-badge {
  font-size: 11px;
  background: var(--bg);
  border: 1px solid var(--border);
