:root {
  --bg: #0d1117;
  --surface: #161b22;
  --border: #30363d;
  --text: #e6edf3;
  --text-muted: #8b949e;
  --accent: #58a6ff;
  --success: #3fb950;
  --warning: #d29922;
  --error: #f85149;
  --radius: 6px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body { background: var(--bg); color: var(--text); font-family: -apple-system, "Segoe UI", system-ui, sans-serif; font-size: 14px; line-height: 1.6; }
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }

/* ── Spinner ──────────────────────────────────────── */
@keyframes spin { to { transform: rotate(360deg); } }
.spinner {
  display: inline-block;
  width: 16px;
  height: 16px;
  border: 2px solid var(--border);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
  vertical-align: middle;
}
.spinner--lg { width: 32px; height: 32px; border-width: 3px; }

/* ── Landing page ─────────────────────────────────── */
.landing {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}
.landing-inner {
  width: 100%;
  max-width: 560px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}
.landing-logo {
  display: flex;
  align-items: center;
  gap: 12px;
}
.landing-brand {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.5px;
  color: var(--text);
}
.landing-tagline {
  color: var(--text-muted);
  font-size: 16px;
  text-align: center;
}
.landing-form {
  display: flex;
  width: 100%;
  gap: 8px;
  margin-top: 8px;
}
.landing-input {
  flex: 1;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  padding: 10px 14px;
  font-size: 14px;
  outline: none;
  transition: border-color 0.15s;
}
.landing-input:focus { border-color: var(--accent); }
.landing-input::placeholder { color: var(--text-muted); }
.landing-btn {
  background: var(--accent);
  color: #0d1117;
  border: none;
  border-radius: var(--radius);
  padding: 10px 20px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
  transition: opacity 0.15s;
}
.landing-btn:disabled { opacity: 0.6; cursor: not-allowed; }
.landing-error {
  color: var(--error);
  font-size: 13px;
  text-align: center;
}

/* ── Dashboard ────────────────────────────────────── */
.dashboard {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}
.dash-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  padding: 12px 24px;
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}
.dash-back { font-size: 13px; color: var(--text-muted); flex-shrink: 0; }
.dash-back:hover { color: var(--accent); }
.dash-title {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1;
}
.dash-name { font-size: 16px; font-weight: 600; }
.status-badge {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  border: 1px solid;
  border-radius: 20px;
  padding: 1px 8px;
  letter-spacing: 0.4px;
}
.dash-repo-link { font-size: 12px; color: var(--text-muted); word-break: break-all; }
.dash-error-banner {
  background: #2d1b1b;
  color: var(--error);
  border-bottom: 1px solid var(--error);
  padding: 10px 24px;
  font-size: 13px;
}
.dash-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex: 1;
  padding: 64px;
  color: var(--text-muted);
}
.dash-tabs {
  display: flex;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
  padding: 0 24px;
  gap: 0;
  overflow-x: auto;
}
.dash-tab {
  background: none;
  border: none;
  color: var(--text-muted);
  padding: 12px 16px;
  cursor: pointer;
  font-size: 14px;
  border-bottom: 2px solid transparent;
  white-space: nowrap;
  transition: color 0.15s, border-color 0.15s;
}
.dash-tab:hover { color: var(--text); }
.dash-tab--active { color: var(--accent); border-bottom-color: var(--accent); }
.dash-content { padding: 24px; flex: 1; }
.panel-loading {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--text-muted);
  padding: 32px 0;
}

/* ── Overview panel ───────────────────────────────── */
.overview-panel { max-width: 700px; display: flex; flex-direction: column; gap: 24px; }
.overview-header { display: flex; flex-direction: column; gap: 4px; }
.overview-name { font-size: 22px; font-weight: 700; }
.overview-url { font-size: 13px; color: var(--text-muted); word-break: break-all; }
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
.stat-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}
.stat-value { font-size: 28px; font-weight: 700; color: var(--accent); }
.stat-label { font-size: 12px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px; }
.overview-section { display: flex; flex-direction: column; gap: 10px; }
.section-title { font-size: 13px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px; color: var(--text-muted); }
.chip-list { display: flex; flex-wrap: wrap; gap: 8px; }
.chip {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 2px 12px;
  font-size: 13px;
  color: var(--text);
}
.detail-list { display: grid; grid-template-columns: auto 1fr; gap: 6px 16px; }
.detail-list dt { color: var(--text-muted); font-size: 13px; }
.detail-list dd { color: var(--text); font-size: 13px; }
.detail-list code { font-size: 11px; color: var(--text-muted); background: var(--bg); padding: 1px 6px; border-radius: 4px; }

/* ── Technologies panel ───────────────────────────── */
.tech-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 12px;
}
.tech-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.tech-card-header { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.tech-name { font-weight: 600; font-size: 14px; }
.tech-version-badge {
  font-size: 11px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 1px 7px;
  color: var(--accent);
  white-space: nowrap;
}
.tech-version-badge--unknown { color: var(--text-muted); }
.tech-source { font-size: 12px; color: var(--text-muted); }
.tech-source em { font-style: normal; color: var(--text); }
.confidence-bar-wrap {
  height: 4px;
  background: var(--border);
  border-radius: 2px;
  overflow: hidden;
}
.confidence-bar { height: 100%; border-radius: 2px; transition: width 0.3s; }
.confidence-label { font-size: 11px; color: var(--text-muted); }

/* ── Dependencies panel ───────────────────────────── */
.deps-panel { display: flex; flex-direction: column; gap: 28px; }
.deps-group-title {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text-muted);
  margin-bottom: 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border);
}
.deps-list { list-style: none; display: flex; flex-direction: column; gap: 2px; }
.deps-item { display: flex; align-items: baseline; gap: 0; padding: 4px 8px; border-radius: var(--radius); }
.deps-item:hover { background: var(--surface); }
.deps-name { color: var(--text); font-size: 13px; }
.deps-version { color: var(--text-muted); font-size: 12px; }

/* ── Repository panel ─────────────────────────────── */
.repo-panel { font-family: "Menlo", "Consolas", monospace; font-size: 13px; }
.tree-dir {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  background: none;
  border: none;
  color: var(--text);
  cursor: pointer;
  padding: 3px 8px;
  text-align: left;
  border-radius: 4px;
}
.tree-dir:hover { background: var(--surface); }
.tree-toggle { color: var(--text-muted); font-size: 11px; width: 12px; flex-shrink: 0; }
.tree-dir-name { font-weight: 600; }
.tree-file {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 2px 8px;
